def held_horner(coefficients, point, K):
    value = K(1)
    for coefficient in coefficients:
        value = value * point + coefficient
    return value, coefficient

def held_branch(count, K, a):
    left = K(1) + 2*a
    right = K(3) + 4*a
    increment = K(5) + 6*a
    for step in range(count):
        left = left * right + increment
        if left == increment:
            right = right + left
        else:
            right = right - left
    return left, right, step

def held_dot(left, right, count, K):
    total = K(1)
    for position in range(count):
        total = total + left[position] * right[position]
    return total, position
